package com.hassan.hisn;

/** Section (book) names: Arabic mode uses the standard Arabic book names for the two Sahih collections; other books show a number. English mode shows the English names given by the data source. */
public class HadithNames {
    static final String[] BUKHARI = {"بدء الوحي","الإيمان","العلم","الوضوء","الغسل","الحيض","التيمم","الصلاة","مواقيت الصلاة","الأذان","الجمعة","صلاة الخوف","العيدين","الوتر","الاستسقاء","الكسوف","سجود القرآن","تقصير الصلاة","التهجد","فضل الصلاة في مسجد مكة والمدينة","العمل في الصلاة","السهو","الجنائز","الزكاة","الحج","العمرة","المحصر","جزاء الصيد","فضائل المدينة","الصوم","صلاة التراويح","فضل ليلة القدر","الاعتكاف","البيوع","السلم","الشفعة","الإجارة","الحوالات","الكفالة","الوكالة","المزارعة","المساقاة","الاستقراض وأداء الديون والحجر والتفليس","الخصومات","اللقطة","المظالم والغصب","الشركة","الرهن","العتق","المكاتب","الهبة وفضلها والتحريض عليها","الشهادات","الصلح","الشروط","الوصايا","الجهاد والسير","فرض الخمس","الجزية والموادعة","بدء الخلق","أحاديث الأنبياء","المناقب","فضائل أصحاب النبي ﷺ","مناقب الأنصار","المغازي","التفسير","فضائل القرآن","النكاح","الطلاق","النفقات","الأطعمة","العقيقة","الذبائح والصيد","الأضاحي","الأشربة","المرضى","الطب","اللباس","الأدب","الاستئذان","الدعوات","الرقاق","القدر","الأيمان والنذور","كفارات الأيمان","الفرائض","الحدود","الديات","استتابة المرتدين والمعاندين وقتالهم","الإكراه","الحيل","التعبير","الفتن","الأحكام","التمني","أخبار الآحاد","الاعتصام بالكتاب والسنة","التوحيد"}; // ids 1..97
    static final String[] MUSLIM = {"المقدمة","الإيمان","الطهارة","الحيض","الصلاة","المساجد ومواضع الصلاة","صلاة المسافرين وقصرها","الجمعة","صلاة العيدين","الاستسقاء","الكسوف","الجنائز","الزكاة","الصيام","الاعتكاف","الحج","النكاح","الرضاع","الطلاق","اللعان","العتق","البيوع","المساقاة","الفرائض","الهبات","الوصية","النذر","الأيمان","القسامة والمحاربين والقصاص والديات","الحدود","الأقضية","اللقطة","الجهاد والسير","الإمارة","الصيد والذبائح وما يؤكل من الحيوان","الأضاحي","الأشربة","اللباس والزينة","الآداب","السلام","الألفاظ من الأدب وغيرها","الشعر","الرؤيا","الفضائل","فضائل الصحابة","البر والصلة والآداب","القدر","العلم","الذكر والدعاء والتوبة والاستغفار","الرقاق","التوبة","صفات المنافقين وأحكامهم","صفة القيامة والجنة والنار","الجنة وصفة نعيمها وأهلها","الفتن وأشراط الساعة","الزهد والرقائق","التفسير"}; // ids 0..56

    public static String name(String ed, int id, String en) {
        if (L.en()) return en;
        if (en == null || en.isEmpty()) return L.s("مقدمة");
        String ar = null;
        if (ed.equals("ara-bukhari") && id >= 1 && id <= BUKHARI.length) ar = BUKHARI[id - 1];
        else if (ed.equals("ara-muslim") && id >= 0 && id < MUSLIM.length) ar = MUSLIM[id];
        if (ar != null) return id == 0 && ed.equals("ara-muslim") ? ar : L.s("كتاب ") + ar;
        return L.s("كتاب رقم ") + Ui.ar(id);
    }
}
